/*
 * libtest.c -- LDG milestone M2 acceptance test (TASK/LDG-M2): the five
 * third-party libraries zView's codecs need -- zlib 1.3.2, libpng 1.6.59,
 * IJG libjpeg 9f, giflib 6.1.3, libexif 0.6.26 -- built UNMODIFIED as NewTOS
 * static libraries, exercised with real round trips on bundled test files.
 *
 * Every test file is embedded (libtest-data.h, generated by gen-data.py),
 * written to the current directory and decoded through the same FILE / path
 * entry points zView's codecs use (png_init_io, jpeg_stdio_src,
 * DGifOpenFileName, exif_data_new_from_data on the saved APP1 marker), so
 * mintlib's stdio/open/lseek are exercised too. Each result is reduced to a
 * CRC-32 (own bitwise implementation, NOT zlib's, so a zlib defect cannot
 * hide in the checksum) plus a length, and compared with
 *   - py_refs[]   (libtest-data.h): computed by gen-data.py without the
 *                 libraries under test (see its header), and/or
 *   - host_refs[] (libtest-ref.h): the same library sources built for the
 *                 host, running this very file (make-ref.sh).
 * A result must match every reference that exists for it, and must have at
 * least one. Checks that are pure self-consistency (decode == source after a
 * write round trip, memory decode == file decode, ...) are marked "self".
 *
 *   zlib    crc32()/adler32() of an LCG buffer; compress2 -> uncompress round
 *           trip (+ the compressed stream's CRC vs host); inflate a stream
 *           made by Python's zlib; gzwrite -> gzread through a file.
 *   libpng  six PNGs (RGB8 with tEXt, RGBA8 Adam7, palette-4 Adam7 + tRNS,
 *           gray-16, gray-1, gray+alpha; every filter type on every image)
 *           decoded to RGBA8 the way pngldg.c reads (expand, strip_16,
 *           gray_to_rgb, interlace handling, png_read_row); png_get_text;
 *           an RGB image written with all filters and read back.
 *   libjpeg baseline 4:2:0, progressive 4:4:4, grayscale, and one with EXIF +
 *           COM markers, decoded via jpeg_stdio_src (J1 also via
 *           jpeg_mem_src); a synthetic image encoded via jpeg_stdio_dest and
 *           decoded back.
 *   giflib  plain, interlaced + transparency + comment, 2-frame animation,
 *           read with the record loop of gifldg.c (DGifGetRecordType /
 *           DGifGetImageDesc / DGifGetLine with the interlace offsets /
 *           DGifGetExtension[Next]).
 *   libexif the J4 APP1 marker: tag names + values as jpgldg.c formats them,
 *           and the embedded thumbnail (exifData->data) decoded with libjpeg.
 *
 * Output (target): one "libtest: PASS|FAIL <name> ..." line per check over
 * Cconws and the verdict "libtest: ALL PASS (N checks)" or "libtest: FAIL (k
 * of N checks failed)". Host: the same on stdout; with -DLIBTEST_EMIT the
 * host build prints the host_refs[] table instead (make-ref.sh).
 *
 * Build: sdk/examples/libtest/build-libtest.sh (target),
 *        sdk/examples/libtest/make-ref.sh      (host references).
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <setjmp.h>
#include <zlib.h>
#include <png.h>
#include <jpeglib.h>
#include <gif_lib.h>
#include <libexif/exif-data.h>
#include <libexif/exif-utils.h>
#ifndef LIBTEST_HOST
#include <mint/osbind.h>
#endif

struct ref { const char *name; unsigned long crc; unsigned long len; };
#include "libtest-data.h"
#ifndef LIBTEST_EMIT
#include "libtest-ref.h"
#endif

/* ---------------------------------------------------------------- output */
static void
out(const char *s)
{
#ifdef LIBTEST_HOST
	fputs(s, stdout);
#else
	Cconws(s);
#endif
}

static unsigned checks, failed;

static void
verdict(const char *name, int ok, const char *detail)
{
	char line[256];
	checks++;
	if (!ok)
		failed++;
#ifdef LIBTEST_EMIT
	if (!ok) {
		snprintf(line, sizeof line, "/* FAIL %s %s */\n", name, detail ? detail : "");
		out(line);
	}
	return;
#endif
	snprintf(line, sizeof line, "libtest: %s %s%s%s\r\n", ok ? "PASS" : "FAIL", name,
	         detail ? " " : "", detail ? detail : "");
	out(line);
}

static void
info(const char *s)
{
#ifndef LIBTEST_EMIT
	out("libtest: info ");
	out(s);
	out("\r\n");
#else
	(void)s;
#endif
}

/* CRC-32 (IEEE 802.3, reflected, poly 0xEDB88320) -- deliberately not zlib's. */
static unsigned long
crc32_own(const unsigned char *p, unsigned long n)
{
	unsigned long c = 0xFFFFFFFFul;
	unsigned long i;
	int k;
	for (i = 0; i < n; i++) {
		c ^= p[i];
		for (k = 0; k < 8; k++)
			c = (c >> 1) ^ (0xEDB88320ul & (0ul - (c & 1)));
	}
	return (c ^ 0xFFFFFFFFul) & 0xFFFFFFFFul;
}

static const struct ref *
find_ref(const struct ref *t, const char *name)
{
	for (; t && t->name; t++)
		if (strcmp(t->name, name) == 0)
			return t;
	return NULL;
}

/* result: compare <name>'s CRC/length with every reference that exists.
 * EMIT (host reference run): print the host_refs[] line, and still check
 * against the Python reference so a host-side defect cannot become a
 * reference. */
static void
result(const char *name, const unsigned char *p, unsigned long n)
{
	unsigned long c = crc32_own(p, n);
	const struct ref *py = find_ref(py_refs, name);
	char d[160];
#ifdef LIBTEST_EMIT
	const struct ref *h = NULL;
	snprintf(d, sizeof d, "  { \"%s\", 0x%08lxu, %luu },\n", name, c, n);
	out(d);
#else
	const struct ref *h = find_ref(host_refs, name);
#endif
	int ok = (h || py);
#ifdef LIBTEST_EMIT
	ok = 1;
#endif
	if (h && (h->crc != c || h->len != n)) ok = 0;
	if (py && (py->crc != c || py->len != n)) ok = 0;
	snprintf(d, sizeof d, "crc=%08lx len=%lu [%s%s%s]", c, n,
	         py ? "py" : "", (py && h) ? "+" : "", h ? "host" : "");
	if (!ok) {
		if (!h && !py)
			snprintf(d + strlen(d), sizeof d - strlen(d), " NO REFERENCE");
		if (py && (py->crc != c || py->len != n))
			snprintf(d + strlen(d), sizeof d - strlen(d), " want(py) %08lx/%lu", py->crc, py->len);
		if (h && (h->crc != c || h->len != n))
			snprintf(d + strlen(d), sizeof d - strlen(d), " want(host) %08lx/%lu", h->crc, h->len);
	}
	verdict(name, ok, d);
}

static void
self(const char *name, int ok, const char *detail)
{
	char n[64];
	snprintf(n, sizeof n, "%s (self)", name);
	verdict(n, ok, detail);
}

static const struct blob *
blob(const char *name)
{
	const struct blob *b;
	for (b = blobs; b->name; b++)
		if (strcmp(b->name, name) == 0)
			return b;
	return NULL;
}

/* Write an embedded file to disk as <name>.TMP; returns the file name. */
static const char *
put_file(const char *name)
{
	static char fn[32];
	const struct blob *b = blob(name);
	FILE *f;
	snprintf(fn, sizeof fn, "LT_%s.TMP", name);
	if (!b) return NULL;
	f = fopen(fn, "wb");
	if (!f) return NULL;
	if (fwrite(b->p, 1, b->len, f) != b->len) { fclose(f); return NULL; }
	if (fclose(f) != 0) return NULL;
	return fn;
}

static unsigned char *
slurp(const char *fn, unsigned long *len)
{
	FILE *f = fopen(fn, "rb");
	unsigned char *p = NULL;
	unsigned long n = 0, cap = 0;
	size_t r;
	if (!f) return NULL;
	for (;;) {
		if (n == cap) {
			unsigned char *q;
			cap = cap ? cap * 2 : 4096;
			q = realloc(p, cap);
			if (!q) { free(p); fclose(f); return NULL; }
			p = q;
		}
		r = fread(p + n, 1, cap - n, f);
		if (r == 0) break;
		n += r;
	}
	fclose(f);
	*len = n;
	return p;
}

/* ------------------------------------------------------------------ zlib */
static void
lcg_text(unsigned char *buf, unsigned long n, unsigned long seed)
{
	static const char alpha[] = "NewTOS zlib round trip ABCDEFGH\n";   /* 32 */
	unsigned long x = seed & 0xFFFFFFFFul, i;
	for (i = 0; i < n; i++) {
		x = (x * 1103515245ul + 12345ul) & 0xFFFFFFFFul;
		buf[i] = (unsigned char)alpha[(x >> 16) & 31];
	}
}

static void
test_zlib(void)
{
	unsigned char *src = malloc(ZBUF_LEN), *cmp, *back;
	uLongf clen, blen;
	unsigned long v;
	const struct blob *b;
	int rc;
	char d[96];
	gzFile gz;

	snprintf(d, sizeof d, "zlibVersion()=%s ZLIB_VERSION=%s", zlibVersion(), ZLIB_VERSION);
	info(d);
	if (!src) { verdict("Z.alloc", 0, NULL); return; }
	lcg_text(src, ZBUF_LEN, ZBUF_SEED);

	/* crc32 / adler32: reduce the 32-bit value to bytes so result() can
	 * compare it (the reference stores the value itself as "crc"). */
	v = crc32(0L, Z_NULL, 0);
	v = crc32(v, src, ZBUF_LEN);
	{
		const struct ref *r = find_ref(py_refs, "Z.crc32");
		snprintf(d, sizeof d, "crc32()=%08lx want %08lx", v, r ? r->crc : 0ul);
		verdict("Z.crc32", r && r->crc == v && r->len == ZBUF_LEN, d);
	}
	v = adler32(0L, Z_NULL, 0);
	v = adler32(v, src, ZBUF_LEN);
	{
		const struct ref *r = find_ref(py_refs, "Z.adler32");
		snprintf(d, sizeof d, "adler32()=%08lx want %08lx", v, r ? r->crc : 0ul);
		verdict("Z.adler32", r && r->crc == v && r->len == ZBUF_LEN, d);
	}

	/* compress2 -> uncompress */
	clen = compressBound(ZBUF_LEN);
	cmp = malloc(clen);
	back = malloc(ZBUF_LEN);
	if (!cmp || !back) { verdict("Z.alloc", 0, NULL); free(src); free(cmp); free(back); return; }
	rc = compress2(cmp, &clen, src, ZBUF_LEN, 6);
	snprintf(d, sizeof d, "rc=%d %lu -> %lu bytes", rc, (unsigned long)ZBUF_LEN, (unsigned long)clen);
	self("Z.compress2", rc == Z_OK && clen < ZBUF_LEN * 3 / 4, d);
	if (rc == Z_OK)
		result("Z.deflate-stream", cmp, clen);
	blen = ZBUF_LEN;
	rc = uncompress(back, &blen, cmp, clen);
	snprintf(d, sizeof d, "rc=%d len=%lu", rc, (unsigned long)blen);
	self("Z.uncompress==source", rc == Z_OK && blen == ZBUF_LEN && memcmp(back, src, ZBUF_LEN) == 0, d);

	/* a stream made by another deflate implementation (Python's zlib) */
	b = blob("ZPY");
	{
		uLongf ol = 32768;
		unsigned char *o = malloc(ol);
		if (o && b) {
			rc = uncompress(o, &ol, b->p, b->len);
			if (rc == Z_OK)
				result("Z.inflate-py", o, ol);
			else {
				snprintf(d, sizeof d, "uncompress rc=%d", rc);
				verdict("Z.inflate-py", 0, d);
			}
		}
		free(o);
	}

	/* gz file round trip (open/write/lseek/read through mintlib) */
	gz = gzopen("LT_Z.GZ", "wb9");
	rc = gz ? gzwrite(gz, src, ZBUF_LEN) : -1;
	rc = (rc == (int)ZBUF_LEN) && gz && gzclose(gz) == Z_OK;
	if (!rc) {
		verdict("Z.gzwrite", 0, NULL);
	} else {
		int n;
		memset(back, 0, ZBUF_LEN);
		gz = gzopen("LT_Z.GZ", "rb");
		n = gz ? gzread(gz, back, ZBUF_LEN) : -1;
		snprintf(d, sizeof d, "gzread=%d eof=%d", n, gz ? gzeof(gz) : -1);
		if (gz) gzclose(gz);
		self("Z.gzwrite->gzread==source", n == (int)ZBUF_LEN && memcmp(back, src, ZBUF_LEN) == 0, d);
	}
	remove("LT_Z.GZ");
	free(src); free(cmp); free(back);
}

/* ---------------------------------------------------------------- libpng */
static void
png_quiet(png_structp p, png_const_charp m)
{
	(void)p; (void)m;
}

static void
test_png_file(const char *name)
{
	char n[32], d[160];
	const char *fn = put_file(name);
	FILE *f;
	png_structp png = NULL;
	png_infop pi = NULL;
	unsigned char *img = NULL;
	png_uint_32 w, h, y;
	int ct, bd, il, passes, p;
	png_size_t rb;

	snprintf(n, sizeof n, "%s.rgba", name);
	if (!fn || !(f = fopen(fn, "rb"))) { verdict(n, 0, "cannot write/open test file"); return; }
	png = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, png_quiet);
	pi = png ? png_create_info_struct(png) : NULL;
	if (!png || !pi) { verdict(n, 0, "create"); fclose(f); return; }
	if (setjmp(png_jmpbuf(png))) {
		png_destroy_read_struct(&png, &pi, NULL);
		free(img); fclose(f); remove(fn);
		verdict(n, 0, "libpng error (longjmp)");
		return;
	}
	png_init_io(png, f);
	png_read_info(png, pi);
	w = png_get_image_width(png, pi);
	h = png_get_image_height(png, pi);
	ct = png_get_color_type(png, pi);
	bd = png_get_bit_depth(png, pi);
	il = png_get_interlace_type(png, pi);
	png_set_expand(png);
	png_set_strip_16(png);
	png_set_gray_to_rgb(png);
	if (!(ct & PNG_COLOR_MASK_ALPHA) && !png_get_valid(png, pi, PNG_INFO_tRNS))
		png_set_add_alpha(png, 0xff, PNG_FILLER_AFTER);
	passes = png_set_interlace_handling(png);
	png_read_update_info(png, pi);
	rb = png_get_rowbytes(png, pi);
	snprintf(d, sizeof d, "%lux%lu type %d depth %d interlace %d passes %d rowbytes %lu channels %d",
	         (unsigned long)w, (unsigned long)h, ct, bd, il, passes, (unsigned long)rb,
	         png_get_channels(png, pi));
	info(d);
	if (rb != (png_size_t)w * 4) {
		png_destroy_read_struct(&png, &pi, NULL); fclose(f); remove(fn);
		verdict(n, 0, "rowbytes != width*4");
		return;
	}
	img = calloc(h, rb);
	for (p = 0; p < passes; p++)
		for (y = 0; y < h; y++)
			png_read_row(png, img + y * rb, NULL);
	png_read_end(png, pi);
	if (strcmp(name, "P1") == 0) {
		png_textp t = NULL;
		int nt = png_get_text(png, pi, &t, NULL);
		int ok = nt == 1 && strcmp(t[0].key, "Comment") == 0 && strcmp(t[0].text, "NewTOS libtest") == 0;
		snprintf(d, sizeof d, "png_get_text: %d entr%s, \"%s\"=\"%s\"", nt, nt == 1 ? "y" : "ies",
		         nt > 0 ? t[0].key : "", nt > 0 ? t[0].text : "");
		self("P1.tEXt", ok, d);
	}
	png_destroy_read_struct(&png, &pi, NULL);
	fclose(f);
	remove(fn);
	result(n, img, (unsigned long)h * rb);
	free(img);
}

static void
test_png_write(void)
{
	const png_uint_32 w = 19, h = 13;
	unsigned char src[19 * 13 * 3], *back = NULL, *file;
	png_structp png;
	png_infop pi;
	png_uint_32 x, y;
	unsigned long flen;
	FILE *f;
	char d[96];
	const char *fn = "LT_PW.TMP";

	for (y = 0; y < h; y++)
		for (x = 0; x < w; x++) {
			src[(y * w + x) * 3 + 0] = (unsigned char)(x * 13 + y);
			src[(y * w + x) * 3 + 1] = (unsigned char)(y * 19);
			src[(y * w + x) * 3 + 2] = (unsigned char)((x * y) ^ 0x5a);
		}
	f = fopen(fn, "wb");
	png = png_create_write_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, png_quiet);
	pi = png ? png_create_info_struct(png) : NULL;
	if (!f || !png || !pi) { verdict("PW.write", 0, "create"); if (f) fclose(f); return; }
	if (setjmp(png_jmpbuf(png))) {
		png_destroy_write_struct(&png, &pi);
		fclose(f);
		verdict("PW.write", 0, "libpng error (longjmp)");
		return;
	}
	png_init_io(png, f);
	png_set_IHDR(png, pi, w, h, 8, PNG_COLOR_TYPE_RGB, PNG_INTERLACE_NONE,
	             PNG_COMPRESSION_TYPE_DEFAULT, PNG_FILTER_TYPE_DEFAULT);
	png_set_filter(png, PNG_FILTER_TYPE_BASE, PNG_ALL_FILTERS);
	png_write_info(png, pi);
	for (y = 0; y < h; y++)
		png_write_row(png, src + y * w * 3);
	png_write_end(png, pi);
	png_destroy_write_struct(&png, &pi);
	fclose(f);

	file = slurp(fn, &flen);
	if (!file) { verdict("PW.file", 0, "cannot read back"); return; }
	result("PW.file", file, flen);
	free(file);

	/* read it back, untransformed RGB8 */
	f = fopen(fn, "rb");
	png = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, png_quiet);
	pi = png ? png_create_info_struct(png) : NULL;
	if (!f || !png || !pi) { verdict("PW.read", 0, "create"); if (f) fclose(f); return; }
	if (setjmp(png_jmpbuf(png))) {
		png_destroy_read_struct(&png, &pi, NULL);
		fclose(f); free(back);
		verdict("PW.read", 0, "libpng error (longjmp)");
		return;
	}
	png_init_io(png, f);
	png_read_info(png, pi);
	back = malloc(w * h * 3);
	for (y = 0; y < h; y++)
		png_read_row(png, back + y * w * 3, NULL);
	png_read_end(png, pi);
	png_destroy_read_struct(&png, &pi, NULL);
	fclose(f);
	remove(fn);
	snprintf(d, sizeof d, "%lu-byte PNG", flen);
	self("PW.write->read==source", memcmp(back, src, sizeof src) == 0, d);
	free(back);
}

static void
test_png(void)
{
	char d[96];
	snprintf(d, sizeof d, "png_get_libpng_ver()=%s PNG_LIBPNG_VER_STRING=%s",
	         png_get_libpng_ver(NULL), PNG_LIBPNG_VER_STRING);
	info(d);
	test_png_file("P1");
	test_png_file("P2");
	test_png_file("P3");
	test_png_file("P4");
	test_png_file("P5");
	test_png_file("P6");
	test_png_write();
}

/* --------------------------------------------------------------- libjpeg */
struct jerr { struct jpeg_error_mgr pub; jmp_buf jb; };

static void
j_errjmp(j_common_ptr c)
{
	longjmp(((struct jerr *)c->err)->jb, 1);
}

static void
j_quiet(j_common_ptr c, int lvl)
{
	(void)c; (void)lvl;
}

#define M_EXIF (JPEG_APP0 + 1)

static unsigned char *exif_app1;         /* J4's APP1, for the libexif test */
static unsigned long exif_app1_len;

/* Decode <fn> (or, with mem != NULL, the memory buffer) the way jpgldg.c
 * does; returns the pixels, sets *n. */
static unsigned char *
jpeg_decode(const char *label, FILE *f, const unsigned char *mem, unsigned long mlen,
            int keep_markers, unsigned long *n, char *d, size_t dl)
{
	struct jpeg_decompress_struct cinfo;
	struct jerr je;
	unsigned char *img = NULL;
	JSAMPROW row;
	unsigned long stride;

	(void)label;
	cinfo.err = jpeg_std_error(&je.pub);
	je.pub.error_exit = j_errjmp;
	je.pub.emit_message = j_quiet;
	if (setjmp(je.jb)) {
		jpeg_destroy_decompress(&cinfo);
		free(img);
		snprintf(d, dl, "libjpeg error");
		return NULL;
	}
	jpeg_create_decompress(&cinfo);
	if (mem)
		jpeg_mem_src(&cinfo, (unsigned char *)mem, mlen);
	else
		jpeg_stdio_src(&cinfo, f);
	if (keep_markers) {
		jpeg_save_markers(&cinfo, JPEG_COM, 0xffff);
		jpeg_save_markers(&cinfo, M_EXIF, 0xffff);
	}
	jpeg_read_header(&cinfo, TRUE);
	if (keep_markers) {
		jpeg_saved_marker_ptr m;
		int com = 0;
		for (m = cinfo.marker_list; m; m = m->next) {
			if (m->marker == JPEG_COM && m->data_length == 22 &&
			    memcmp(m->data, "NewTOS libtest comment", 22) == 0)
				com = 1;
			if (m->marker == M_EXIF && !exif_app1) {
				exif_app1 = malloc(m->data_length);
				if (exif_app1) {
					memcpy(exif_app1, m->data, m->data_length);
					exif_app1_len = m->data_length;
				}
			}
		}
		self("J4.COM-marker", com, NULL);
	}
	if (cinfo.num_components == 3 || cinfo.jpeg_color_space == JCS_YCbCr)
		cinfo.out_color_space = JCS_RGB;
	jpeg_start_decompress(&cinfo);
	stride = (unsigned long)cinfo.output_width * cinfo.output_components;
	img = malloc(stride * cinfo.output_height);
	while (cinfo.output_scanline < cinfo.output_height) {
		row = img + cinfo.output_scanline * stride;
		jpeg_read_scanlines(&cinfo, &row, 1);
	}
	snprintf(d, dl, "%ux%u x%d %s%s", cinfo.output_width, cinfo.output_height,
	         cinfo.output_components, cinfo.progressive_mode ? "progressive" : "baseline",
	         cinfo.arith_code ? " arith" : "");
	*n = stride * cinfo.output_height;
	jpeg_finish_decompress(&cinfo);
	jpeg_destroy_decompress(&cinfo);
	return img;
}

static void
test_jpeg_file(const char *name, int markers)
{
	char n[32], d[96];
	unsigned long len;
	unsigned char *img;
	const char *fn = put_file(name);
	FILE *f = fn ? fopen(fn, "rb") : NULL;

	snprintf(n, sizeof n, "%s.pixels", name);
	if (!f) { verdict(n, 0, "cannot write/open test file"); return; }
	img = jpeg_decode(name, f, NULL, 0, markers, &len, d, sizeof d);
	fclose(f);
	remove(fn);
	if (!img) { verdict(n, 0, d); return; }
	info(d);
	result(n, img, len);
	if (strcmp(name, "J1") == 0) {
		const struct blob *b = blob("J1");
		unsigned long l2;
		unsigned char *m = jpeg_decode("J1mem", NULL, b->p, b->len, 0, &l2, d, sizeof d);
		self("J1.mem_src==stdio_src", m && l2 == len && memcmp(m, img, len) == 0, d);
		free(m);
	}
	free(img);
}

static void
test_jpeg_encode(void)
{
	struct jpeg_compress_struct cinfo;
	struct jerr je;
	const int w = 40, h = 24;
	unsigned char src[40 * 24 * 3], *file, *img;
	JSAMPROW row;
	FILE *f;
	unsigned long flen, len;
	int x, y;
	char d[96];
	const char *fn = "LT_JE.TMP";

	for (y = 0; y < h; y++)
		for (x = 0; x < w; x++) {
			src[(y * w + x) * 3 + 0] = (unsigned char)(x * 6);
			src[(y * w + x) * 3 + 1] = (unsigned char)(255 - y * 10);
			src[(y * w + x) * 3 + 2] = (unsigned char)(((x / 8 + y / 8) & 1) ? 200 : 40);
		}
	f = fopen(fn, "wb");
	if (!f) { verdict("JE.file", 0, "cannot create"); return; }
	cinfo.err = jpeg_std_error(&je.pub);
	je.pub.error_exit = j_errjmp;
	je.pub.emit_message = j_quiet;
	if (setjmp(je.jb)) {
		jpeg_destroy_compress(&cinfo);
		fclose(f);
		verdict("JE.file", 0, "libjpeg error");
		return;
	}
	jpeg_create_compress(&cinfo);
	jpeg_stdio_dest(&cinfo, f);
	cinfo.image_width = w;
	cinfo.image_height = h;
	cinfo.input_components = 3;
	cinfo.in_color_space = JCS_RGB;
	jpeg_set_defaults(&cinfo);
	jpeg_set_quality(&cinfo, 90, TRUE);
	jpeg_start_compress(&cinfo, TRUE);
	while (cinfo.next_scanline < cinfo.image_height) {
		row = src + cinfo.next_scanline * w * 3;
		jpeg_write_scanlines(&cinfo, &row, 1);
	}
	jpeg_finish_compress(&cinfo);
	jpeg_destroy_compress(&cinfo);
	fclose(f);

	file = slurp(fn, &flen);
	if (!file) { verdict("JE.file", 0, "cannot read back"); return; }
	result("JE.file", file, flen);
	free(file);
	f = fopen(fn, "rb");
	img = f ? jpeg_decode("JE", f, NULL, 0, 0, &len, d, sizeof d) : NULL;
	if (f) fclose(f);
	remove(fn);
	if (!img) { verdict("JE.pixels", 0, d); return; }
	result("JE.pixels", img, len);
	{
		/* lossy: just a sanity bound on the error */
		unsigned long i, maxd = 0;
		for (i = 0; i < len && i < sizeof src; i++) {
			int e = (int)img[i] - (int)src[i];
			if (e < 0) e = -e;
			if ((unsigned long)e > maxd) maxd = e;
		}
		snprintf(d, sizeof d, "max |decoded-source| = %lu (bound 64)", maxd);
		self("JE.decode~source", len == sizeof src && maxd <= 64, d);
	}
	free(img);
}

static void
test_jpeg(void)
{
	char d[64];
	snprintf(d, sizeof d, "JPEG_LIB_VERSION=%d (%d%c)", JPEG_LIB_VERSION,
	         JPEG_LIB_VERSION_MAJOR, 'a' + JPEG_LIB_VERSION_MINOR - 1);
	info(d);
	test_jpeg_file("J1", 0);
	test_jpeg_file("J2", 0);
	test_jpeg_file("J3", 0);
	test_jpeg_file("J4", 1);
	test_jpeg_encode();
}

/* ---------------------------------------------------------------- libexif */
static void
test_exif(void)
{
	ExifData *ed;
	int i, l, make_ok = 0;
	char value[1024 + 256];
	char *text;
	size_t tl = 0, cap = 8192;
	char d[128];

	if (!exif_app1) { verdict("E.app1", 0, "J4 had no APP1 marker"); return; }
	ed = exif_data_new_from_data(exif_app1, exif_app1_len);
	if (!ed) { verdict("E.parse", 0, "exif_data_new_from_data == NULL"); return; }
	text = malloc(cap);
	text[0] = 0;
	/* jpgldg.c:379-405, verbatim in substance */
	for (i = 0; i < EXIF_IFD_COUNT; i++) {
		ExifContent *content = ed->ifd[i];
		for (l = 0; l < (int)content->count; l++) {
			ExifEntry *e = content->entries[l];
			size_t len;
			sprintf(value, "%s", exif_tag_get_name(e->tag));
			strcat(value, ": ");
			len = strlen(value);
			exif_entry_get_value(e, &value[len], sizeof(value) - len);
			if (strcmp(value, "Make: NewTOS") == 0)
				make_ok = 1;
			len = strlen(value);
			if (tl + len + 2 < cap) {
				memcpy(text + tl, value, len);
				tl += len;
				text[tl++] = '\n';
				text[tl] = 0;
			}
			info(value);
		}
	}
	snprintf(d, sizeof d, "\"Make: NewTOS\" %s", make_ok ? "found" : "MISSING");
	self("E.Make", make_ok, d);
	result("E.text", (unsigned char *)text, tl);
	free(text);

	/* the thumbnail: exifData->data, decoded like decompress_thumbnail_image */
	if (!ed->data || !ed->size) {
		verdict("E.thumb", 0, "no thumbnail");
	} else {
		unsigned long n;
		unsigned char *img;
		result("E.thumb", ed->data, ed->size);
		img = jpeg_decode("thumb", NULL, ed->data, ed->size, 0, &n, d, sizeof d);
		if (!img)
			verdict("E.thumb.pixels", 0, d);
		else
			result("E.thumb.pixels", img, n);
		free(img);
	}
	exif_data_unref(ed);
	free(exif_app1);
	exif_app1 = NULL;
}

/* ---------------------------------------------------------------- giflib */
static void
test_gif_file(const char *name, int want_images, int want_interlace, const char *want_comment)
{
	static const int off[] = { 0, 4, 2, 1 }, jmp[] = { 8, 8, 4, 2 };
	char n[32], d[160];
	const char *fn = put_file(name);
	GifFileType *gif;
	GifRecordType rec;
	int err = 0, images = 0, ext_gce = 0, comment_ok = want_comment ? 0 : 1, il = -1;
	unsigned char *first = NULL;
	unsigned long first_len = 0;
	ColorMapObject *gct;

	snprintf(n, sizeof n, "%s.index", name);
	if (!fn) { verdict(n, 0, "cannot write test file"); return; }
	gif = DGifOpenFileName(fn, &err);
	if (!gif) {
		snprintf(d, sizeof d, "DGifOpenFileName error %d (%s)", err, GifErrorString(err));
		verdict(n, 0, d); remove(fn); return;
	}
	gct = gif->SColorMap;
	do {
		if (DGifGetRecordType(gif, &rec) == GIF_ERROR) break;
		if (rec == IMAGE_DESC_RECORD_TYPE) {
			int W, H, row, col, i, j;
			unsigned char *buf;
			if (DGifGetImageDesc(gif) == GIF_ERROR) break;
			W = gif->Image.Width; H = gif->Image.Height;
			row = gif->Image.Top; col = gif->Image.Left;
			buf = calloc((size_t)W * H, 1);
			if (!buf) break;
			if (images == 0) il = gif->Image.Interlace ? 1 : 0;
			if (gif->Image.Interlace) {
				for (i = 0; i < 4; i++)
					for (j = off[i]; j < H; j += jmp[i])
						if (DGifGetLine(gif, buf + (size_t)j * W, W) != GIF_OK) goto bad;
			} else {
				for (j = 0; j < H; j++)
					if (DGifGetLine(gif, buf + (size_t)j * W, W) != GIF_OK) goto bad;
			}
			(void)row; (void)col;
			if (images == 0) { first = buf; first_len = (unsigned long)W * H; }
			else free(buf);
			images++;
			continue;
bad:
			free(buf);
			break;
		} else if (rec == EXTENSION_RECORD_TYPE) {
			int code;
			GifByteType *block;
			if (DGifGetExtension(gif, &code, &block) == GIF_ERROR) break;
			if (code == GRAPHICS_EXT_FUNC_CODE) ext_gce++;
			if (code == COMMENT_EXT_FUNC_CODE && want_comment && block &&
			    block[0] == strlen(want_comment) &&
			    memcmp(block + 1, want_comment, block[0]) == 0)
				comment_ok = 1;
			while (block) {
				if (DGifGetExtensionNext(gif, &block) == GIF_ERROR) { block = NULL; break; }
			}
		}
	} while (rec != TERMINATE_RECORD_TYPE);
	snprintf(d, sizeof d, "images %d (want %d), interlace %d (want %d), GCE %d, comment %s, last error %d",
	         images, want_images, il, want_interlace, ext_gce,
	         want_comment ? (comment_ok ? "ok" : "MISSING") : "-", gif->Error);
	self(name, rec == TERMINATE_RECORD_TYPE && images == want_images && il == want_interlace &&
	     comment_ok, d);
	if (first)
		result(n, first, first_len);
	else
		verdict(n, 0, "no image decoded");
	snprintf(n, sizeof n, "%s.gct", name);
	if (gct) {
		unsigned char cm[256 * 3];
		int i;
		for (i = 0; i < gct->ColorCount && i < 256; i++) {
			cm[i * 3 + 0] = gct->Colors[i].Red;
			cm[i * 3 + 1] = gct->Colors[i].Green;
			cm[i * 3 + 2] = gct->Colors[i].Blue;
		}
		result(n, cm, (unsigned long)i * 3);
	} else {
		verdict(n, 0, "no global colour table");
	}
	DGifCloseFile(gif, &err);
	free(first);
	remove(fn);
}

static void
test_gif(void)
{
	char d[64];
	snprintf(d, sizeof d, "GIFLIB %d.%d.%d", GIFLIB_MAJOR, GIFLIB_MINOR, GIFLIB_RELEASE);
	info(d);
	test_gif_file("G1", 1, 0, NULL);
	test_gif_file("G2", 1, 1, "NewTOS gif");
	test_gif_file("G3", 2, 0, NULL);
}

int
main(void)
{
	char d[64];
#ifdef LIBTEST_EMIT
	out("/* libtest-ref.h -- GENERATED by make-ref.sh (TASK/LDG-M2). Do not edit.\n"
	    " * Results of libtest.c built for the HOST against the same pinned library\n"
	    " * sources; the target build must reproduce them bit for bit. */\n"
	    "static const struct ref host_refs[] = {\n");
#else
	out("libtest: start (zlib, libpng, libjpeg, giflib, libexif)\r\n");
#endif
	test_zlib();
	test_png();
	test_jpeg();
	test_exif();
	test_gif();
#ifdef LIBTEST_EMIT
	out("  { 0, 0, 0 }\n};\n");
	snprintf(d, sizeof d, "/* %u results, %u failures while generating */\n", checks, failed);
	out(d);
	return failed != 0;
#else
	if (failed == 0)
		snprintf(d, sizeof d, "libtest: ALL PASS (%u checks)\r\n", checks);
	else
		snprintf(d, sizeof d, "libtest: FAIL (%u of %u checks failed)\r\n", failed, checks);
	out(d);
	return failed != 0;
#endif
}
